-- Add created_at column that Drizzle expects (the DB has camelCase createdAt)
-- First check if created_at already exists
ALTER TABLE team_notifications 
  ADD COLUMN IF NOT EXISTS `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP;

-- Copy existing data from camelCase to snake_case
UPDATE team_notifications SET created_at = createdAt WHERE created_at IS NULL OR created_at = '0000-00-00 00:00:00';
